(* [comment removed for export] *)
Lemma cw_bits_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (v : word) (k mm j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTd m ->
  (0 <= j < wd)%Z -> (0 <= k)%Z -> (32 * k + 32 <= hd)%Z -> (0 <= mm)%Z -> (Z.of_nat n = 31 - mm)%Z ->
  regs_agree (fun x => In x [19; 20; 21; 29]%list) r0 r ->
  getr r 31 = v_lw v -> getr r 19 = Z_to_bv 64 mm -> getr r 29 = Z_to_bv 64 (datad + 4 * wpld * (32 * k + mm)) ->
  getr r 28 = Z_to_bv 64 (4 * (j / 32)) -> getr r 10 = Z_to_bv 64 (4 * wpld) -> getr r 14 = Z_to_bv 64 32 ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTd m' -> regs_agree (fun x => In x [19; 20; 21; 29]%list) r0 r' ->
     getr r' 29 = Z_to_bv 64 (datad + 4 * wpld * (32 * k + 32)) ->
     realizes SEGS (mkCfg (mkst r' (0x87a30 : word) m' al_rom) md) S) ->
