(* [comment removed for export] *)
Lemma cw_words_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (k j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTd m ->
  (0 <= j < wd)%Z -> (0 <= k)%Z -> (Z.of_nat n = hd / 32 - 1 - k)%Z ->
  regs_agree (fun x => In x [7; 19; 20; 21; 29; 31]%list) r0 r ->
  getr r 7 = Z_to_bv 64 k -> getr r 6 = Z_to_bv 64 (datas + 4 * wpls * (wd - 1 - j)) -> getr r 29 = Z_to_bv 64 (datad + 4 * wpld * (32 * k)) ->
  getr r 28 = Z_to_bv 64 (4 * (j / 32)) -> getr r 5 = Z_to_bv 64 (128 * wpld) -> getr r 10 = Z_to_bv 64 (4 * wpld) -> getr r 14 = Z_to_bv 64 32 ->
  getr r 16 = Z_to_bv 64 (hd / 32) -> getr r 2 = Z_to_bv 64 (s - 80) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTd m' -> regs_agree (fun x => In x [7; 19; 20; 21; 29; 31]%list) r0 r' ->
     getr r' 7 = Z_to_bv 64 hd -> getr r' 29 = Z_to_bv 64 (datad + 4 * wpld * (32 * (hd / 32))) ->
     realizes SEGS (mkCfg (mkst r' (0x87a7c : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x87a38 : word) m al_rom) md) S.
