Lemma cw_tail_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (i j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTd m ->
  (0 <= j < wd)%Z -> (0 <= i)%Z -> (Z.of_nat n = hd - 1 - i)%Z ->
  regs_agree (fun x => In x [7; 19; 28; 29; 31]%list) r0 r ->
  getr r 29 = Z_to_bv 64 i -> getr r 6 = Z_to_bv 64 (datas + 4 * wpls * (wd - 1 - j)) ->
  getr r 28 = Z_to_bv 64 (datad + 4 * wpld * i + 4 * (j / 32)) -> getr r 7 = Z_to_bv 64 hd -> getr r 10 = Z_to_bv 64 (4 * wpld) ->
  getr r 2 = Z_to_bv 64 (s - 80) ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTd m' -> regs_agree (fun x => In x [7; 19; 28; 29; 31]%list) r0 r' ->
     getr r' 7 = Z_to_bv 64 hd ->
     realizes SEGS (mkCfg (mkst r' (0x879e8 : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x87a9c : word) m al_rom) md) S.
