(* [comment removed for export] *)
Lemma cw_rows_W : forall (n : nat) (r0 r : bvmap 5 word) (m : word -> option byte) (j : Z),
  W C A m md -> POSTM C Ar s mB m -> FTd m -> (0 <= j)%Z -> (Z.of_nat n = wd - 1 - j)%Z ->
  regs_agree (fun x => In x [6; 7; 11; 12; 19; 20; 21; 28; 29; 30; 31]%list) r0 r ->
  getr r0 5 = Z_to_bv 64 (128 * wpld) -> getr r0 10 = Z_to_bv 64 (4 * wpld) -> getr r0 13 = Z_to_bv 64 hd -> getr r0 14 = Z_to_bv 64 32 ->
  getr r0 16 = Z_to_bv 64 (hd / 32) -> getr r0 17 = Z_to_bv 64 (32 * (hd / 32)) -> getr r0 8 = Z_to_bv 64 datad -> getr r0 9 = Z_to_bv 64 datas ->
  getr r0 18 = Z_to_bv 64 wpls -> getr r0 2 = Z_to_bv 64 (s - 80) ->
  getr r 11 = Z_to_bv 64 j -> getr r 12 = Z_to_bv 64 j -> getr r 6 = Z_to_bv 64 wd -> getr r 7 = Z_to_bv 64 hd ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTd m' -> regs_agree (fun x => In x [6; 7; 11; 12; 19; 20; 21; 28; 29; 30; 31]%list) r0 r' ->
     realizes SEGS (mkCfg (mkst r' (0x88300 : word) m' al_rom) md) S) ->
