  W C A mB md ->
  getr r 2 = Z_to_bv 64 (s - 80) -> getr r 10 = Z_to_bv 64 wpld -> getr r 8 = Z_to_bv 64 datad -> getr r 9 = Z_to_bv 64 datas ->
  getr r 18 = Z_to_bv 64 wpls ->
  (forall m' r', W C A m' md -> POSTM C Ar s mB m' -> FTd m' ->
     regs_agree (fun x => In x [5; 6; 7; 10; 11; 12; 13; 14; 15; 16; 17; 19; 20; 21; 28; 29; 30; 31]%list) r r' ->
     realizes SEGS (mkCfg (mkst r' (0x88300 : word) m' al_rom) md) S) ->
  realizes SEGS (mkCfg (mkst r (0x87958 : word) mB al_rom) md) S.
